#!/usr/bin/env python3
"""The check for lint-all/t3. Generated by eval/build_tasks.py; run it
as `python3 check.py <workspace>`. Exit 0 is a pass."""

import json
import re
import shutil
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[3]))
from checklib import CAMEL, SNAKE, main  # noqa: E402


def check(ws):
    ws.check("./dev lint passes", *ws.dev("lint"))
    ws.check("./dev test passes", *ws.dev("test"))
    ws.check("the task's own assertions", *ws.py('from tally.customers import email_domain, make_customer\nassert email_domain(make_customer("C-1", "Acme", "Billing@Acme.IO", "GB")) == "acme.io"', env=None))


if __name__ == "__main__":
    main(check)
